mapper.select:
SELECT id, tenant_id AS tenantId, next_run_at AS nextRunAt FROM wb_companion_task
WHERE status = 1 AND next_run_at <= #{now}
ORDER BY next_run_at, id
LIMIT #{limit}

mapper.update:
UPDATE wb_companion_task
SET status = 4, pair_code = NULL, error_code = 'STOPPED', finished_at = #{now}, updated_at = #{now}
WHERE id = #{id} AND status = 1

